package com.eventteams;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.Text;

/**
 * Draws team-colored minimap dots. Kept separate from {@link EventTeamsOverlay}
 * because the minimap is part of the widget/interface layer: to paint a dot on
 * top of the game's own minimap dots (e.g. the native green friend dot) the
 * overlay must sit on ABOVE_WIDGETS, whereas the in-world name text belongs on
 * the default UNDER_WIDGETS layer so it doesn't paint over the interface. This
 * mirrors core Player Indicators, which likewise uses a dedicated
 * ABOVE_WIDGETS minimap overlay.
 */
public class EventTeamsMinimapOverlay extends Overlay
{
	private final Client client;
	private final EventTeamsConfig config;
	private final TeamRegistry registry;

	@Inject
	EventTeamsMinimapOverlay(Client client, EventTeamsConfig config, TeamRegistry registry)
	{
		this.client = client;
		this.config = config;
		this.registry = registry;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightOnMinimap())
		{
			return null;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}

		for (Player player : worldView.players())
		{
			if (player == null || player.getName() == null)
			{
				continue;
			}

			Color color = registry.getColorForPlayer(player.getName());
			if (color == null)
			{
				continue;
			}

			Point minimapLocation = player.getMinimapLocation();
			if (minimapLocation != null)
			{
				OverlayUtil.renderMinimapLocation(graphics, minimapLocation, color);

				if (config.showNamesOnMinimap())
				{
					String name = Text.sanitize(player.getName());
					// Center the name above the dot, matching core Player Indicators.
					Point textLocation = new Point(
						minimapLocation.getX() - graphics.getFontMetrics().stringWidth(name) / 2,
						minimapLocation.getY() - 3);
					OverlayUtil.renderTextLocation(graphics, textLocation, name, color);
				}
			}
		}

		return null;
	}
}

package com.eventteams;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("eventteams")
public interface EventTeamsConfig extends Config
{
	// Teams are edited through the side panel, not this config screen — this
	// key just persists the serialized roster between client restarts.
	// Hidden from the normal config GUI since it's raw JSON, not user-facing.
	@ConfigItem(
		keyName = "teamData",
		name = "",
		description = "",
		hidden = true
	)
	default String teamData()
	{
		return "";
	}

	@ConfigItem(
		keyName = "highlightInWorld",
		name = "Highlight players in world",
		description = "Draw team-colored names above players in the game world",
		position = 1
	)
	default boolean highlightInWorld()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightOnMinimap",
		name = "Highlight on minimap",
		description = "Draw a team-colored dot on the minimap for each tracked player",
		position = 2
	)
	default boolean highlightOnMinimap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showNamesOnMinimap",
		name = "Show names on minimap",
		description = "Also draw the player's name next to their minimap dot",
		position = 3
	)
	default boolean showNamesOnMinimap()
	{
		return false;
	}

	@ConfigItem(
		keyName = "tagChatMessages",
		name = "Color names in chat",
		description = "Color a tracked player's name in their team color in public and clan chat",
		position = 4
	)
	default boolean tagChatMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTeamNameInChat",
		name = "Show team name in chat",
		description = "Also prefix the player's name with their team name (after the clan tag, before the name)",
		position = 5
	)
	default boolean showTeamNameInChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightFriendsList",
		name = "Team square in friends list",
		description = "Draw a small team-colored square next to tracked players in the in-game friends list",
		position = 6
	)
	default boolean highlightFriendsList()
	{
		return true;
	}
}

package com.eventteams;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.ScriptID;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.ClanMemberJoined;
import net.runelite.api.events.ClanMemberLeft;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Event Teams",
	description = "Highlights clan event teams in-world and in chat, and tracks online status per team",
	tags = {"bingo", "event", "clan", "teams"}
)
public class EventTeamsPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "eventteams";
	private static final String CONFIG_KEY_TEAM_DATA = "teamData";

	/** Size of the team square drawn in the friends list, and its gap from the name. */
	private static final int MARKER_SIZE = 6;
	private static final int MARKER_GAP = 3;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventTeamsConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ChatIconManager chatIconManager;

	private TeamRegistry registry;
	private EventTeamsOverlay overlay;
	private EventTeamsMinimapOverlay minimapOverlay;
	private EventTeamsPanel panel;
	private NavigationButton navButton;

	@Provides
	EventTeamsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EventTeamsConfig.class);
	}

	@Override
	protected void startUp()
	{
		registry = new TeamRegistry(gson);
		String stored = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_TEAM_DATA);
		registry.loadFromJson(stored);

		overlay = new EventTeamsOverlay(client, config, registry, chatIconManager);
		overlayManager.add(overlay);

		minimapOverlay = new EventTeamsMinimapOverlay(client, config, registry);
		overlayManager.add(minimapOverlay);

		panel = new EventTeamsPanel(this, registry);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Event Teams")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		refreshOnlineStatus();
		log.debug("Event Teams started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(minimapOverlay);
		clientToolbar.removeNavigation(navButton);
		log.debug("Event Teams stopped");
	}

	void saveTeams()
	{
		configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_TEAM_DATA, registry.serialize());
	}

	/**
	 * ClanChannelChanged fires when the local player connects to or leaves a
	 * clan channel; ClanMemberJoined/Left fire as individual members log in and
	 * out (or hop worlds). Together they keep the panel's online dots current.
	 * The clan channel is the "currently connected" view — distinct from
	 * ClanSettings, which is the full roster including offline members.
	 */
	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		refreshOnlineStatus();
	}

	@Subscribe
	public void onClanMemberJoined(ClanMemberJoined event)
	{
		refreshOnlineStatus();
	}

	@Subscribe
	public void onClanMemberLeft(ClanMemberLeft event)
	{
		refreshOnlineStatus();
	}

	private void refreshOnlineStatus()
	{
		Map<String, Integer> onlineWorlds = new HashMap<>();

		// Guest channel included so events spanning a guest clan still track.
		for (ClanChannel channel : new ClanChannel[]{client.getClanChannel(), client.getGuestClanChannel()})
		{
			if (channel == null)
			{
				continue;
			}
			for (ClanChannelMember member : channel.getMembers())
			{
				onlineWorlds.put(TeamRegistry.normalize(member.getName()), member.getWorld());
			}
		}

		if (panel != null)
		{
			panel.updateOnlineStatus(onlineWorlds);
		}
	}

	/**
	 * Colors a rostered player's name in their team color in public and clan
	 * chat, using OSRS's inline <col=RRGGBB> chat markup, leaving the rest of
	 * the line (including the clan channel tag) untouched. Private messages and
	 * messages from players not on a team roster are left untouched.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		if (!config.tagChatMessages())
		{
			return;
		}

		if (chatMessage.getType() != ChatMessageType.PUBLICCHAT
			&& chatMessage.getType() != ChatMessageType.CLAN_CHAT
			&& chatMessage.getType() != ChatMessageType.CLAN_MESSAGE)
		{
			return;
		}

		MessageNode messageNode = chatMessage.getMessageNode();
		if (messageNode == null)
		{
			return;
		}

		String senderName = Text.removeTags(chatMessage.getName());
		if (senderName.isEmpty())
		{
			// System broadcasts (loot drops, level-ups, pbs...) have no sender;
			// the player's name is the start of the message body instead.
			if (chatMessage.getType() == ChatMessageType.CLAN_MESSAGE)
			{
				tagBroadcast(messageNode);
			}
			return;
		}

		TeamInfo team = registry.getTeamForPlayer(senderName);
		if (team == null)
		{
			return;
		}

		// Color the sender's name in their team color, for both public and clan
		// chat, and leave every other part of the line alone — including the
		// clan channel tag (the "[Clan Name]" sender slot). Wrapping the stored
		// name in only a <col> tag is safe for rank icons: they're resolved by
		// matching Text.removeTags(name), which strips the color tag, so the icon
		// still resolves. The optional team-name prefix is deliberately NOT baked
		// into the stored name here — a literal "[Team]" would survive removeTags
		// and break that lookup (demoting clan icons to guest). It's added to the
		// transient build stack instead, in onScriptCallbackEvent below.
		String coloredName = ColorUtil.wrapWithColorTag(messageNode.getName(), team.getColor());

		clientThread.invokeLater(() -> {
			messageNode.setName(coloredName);
			client.refreshChat();
		});
	}

	/**
	 * Adds the optional team tag to public/clan chat lines as they are built, by
	 * editing the object stack rather than the stored MessageNode name. The chat
	 * build stack holds [channel/clan-tag = size-4, username = size-3, message =
	 * size-2]. The clan rank icon is resolved from the username (size-3) *after*
	 * this callback, so that slot must stay clean — a literal "[Team]" there
	 * would fail the lookup and demote everyone's icon to guest.
	 *
	 * So in clan chat we append the team tag to the clan-tag slot (size-4),
	 * rendering "[Clan] [Team] &lt;icon&gt;Player" with the icon intact. Public
	 * chat has no clan tag, so there we prefix the username slot directly.
	 */
	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!"chatMessageBuilding".equals(event.getEventName())
			|| !config.tagChatMessages() || !config.showTeamNameInChat())
		{
			return;
		}

		int uid = client.getIntStack()[client.getIntStackSize() - 1];
		MessageNode messageNode = client.getMessages().get(uid);
		if (messageNode == null)
		{
			return;
		}

		ChatMessageType type = messageNode.getType();
		Object[] objectStack = client.getObjectStack();
		int size = client.getObjectStackSize();

		// Username slot is read (tags stripped) to identify the team either way.
		String name = (String) objectStack[size - 3];
		TeamInfo team = registry.getTeamForPlayer(Text.removeTags(name));
		if (team == null)
		{
			return;
		}

		String coloredTeam = ColorUtil.wrapWithColorTag(team.getName(), team.getColor());

		if (type == ChatMessageType.CLAN_CHAT)
		{
			// Append to the clan-tag slot so it renders as a separate bracketed
			// tag right after the clan tag; the username slot is left untouched
			// so the clan rank icon still resolves. ChatMessageManager wraps this
			// whole slot in the clan color, so close that color (</col>) before
			// the "] [" separator — otherwise the brackets between the two tags
			// inherit the clan color instead of the default text color.
			String channel = (String) objectStack[size - 4];
			objectStack[size - 4] = channel + "</col>] [" + coloredTeam;
		}
		else if (type == ChatMessageType.PUBLICCHAT)
		{
			objectStack[size - 3] = "[" + coloredTeam + "] " + name;
		}
	}

	/**
	 * Draws a small team-colored square beside tracked players' names in the
	 * in-game friends list, leaving the name itself in its normal color.
	 * FRIENDS_UPDATE rebuilds the list (wiping the squares along with the rest of
	 * the dynamic children), so we re-add them after it fires. Rather than assume
	 * a fixed child layout per row, every text child is matched against the
	 * roster — the world/status columns simply never match a name.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.FRIENDS_UPDATE || !config.highlightFriendsList())
		{
			return;
		}

		Widget list = client.getWidget(InterfaceID.Friends.LIST);
		if (list == null)
		{
			return;
		}

		Widget[] children = list.getDynamicChildren();
		if (children == null)
		{
			return;
		}

		// Collect the matches first — createChild() below appends to the same
		// dynamic-children array we'd otherwise be iterating.
		Map<Widget, Color> marked = new LinkedHashMap<>();
		for (Widget child : children)
		{
			String text = child.getText();
			if (text == null || text.isEmpty())
			{
				continue;
			}

			Color color = registry.getColorForPlayer(Text.removeTags(text));
			if (color != null)
			{
				marked.put(child, color);
			}
		}

		for (Map.Entry<Widget, Color> entry : marked.entrySet())
		{
			Widget name = entry.getKey();

			// Anchor the square just past the end of the rendered name text, not
			// the name widget's right edge — the widget spans the whole column,
			// so its edge sits in whitespace next to the World column.
			int size = markerSize(name);
			int markerX = name.getOriginalX() + textWidth(name) + MARKER_GAP;

			nudgeIconsClear(children, name, markerX, size);

			Widget marker = list.createChild(-1, WidgetType.RECTANGLE);
			marker.setFilled(true);
			marker.setOpacity(0);
			marker.setTextColor(entry.getValue().getRGB() & 0xFFFFFF);
			marker.setOriginalWidth(size);
			marker.setOriginalHeight(size);
			marker.setOriginalX(markerX);
			marker.setOriginalY(name.getOriginalY() + (name.getOriginalHeight() - size) / 2);
			marker.revalidate();
		}
	}

	/**
	 * Size of the team square. Grows a pixel when the row height's parity would
	 * otherwise leave the square half a pixel off-center — an even square can
	 * only sit dead-center in an even row, so match the row's parity and the
	 * centering divides exactly instead of truncating a pixel high.
	 */
	private static int markerSize(Widget name)
	{
		return (name.getOriginalHeight() - MARKER_SIZE) % 2 == 0 ? MARKER_SIZE : MARKER_SIZE + 1;
	}

	/**
	 * Shifts any icon that would sit underneath the team square out to its right
	 * — chiefly the "recently renamed" indicator the game draws immediately after
	 * a name. Restricted to GRAPHIC children on the same row that actually
	 * overlap the square, so text columns (e.g. World) are never moved.
	 */
	private static void nudgeIconsClear(Widget[] children, Widget name, int markerX, int size)
	{
		for (Widget child : children)
		{
			if (child == name || child.getType() != WidgetType.GRAPHIC || !sameRow(child, name))
			{
				continue;
			}

			int x = child.getOriginalX();
			boolean overlaps = x < markerX + size && x + child.getOriginalWidth() > markerX;
			if (overlaps)
			{
				child.setOriginalX(x + size + MARKER_GAP);
				child.revalidate();
			}
		}
	}

	/** Whether two widgets' vertical extents overlap, i.e. share a list row. */
	private static boolean sameRow(Widget a, Widget b)
	{
		int aTop = a.getOriginalY();
		int bTop = b.getOriginalY();
		return aTop < bTop + b.getOriginalHeight() && bTop < aTop + a.getOriginalHeight();
	}

	/**
	 * Rendered width of a text widget's contents, or its full width if the font
	 * isn't available yet (which would place the square at the column edge rather
	 * than drop it entirely).
	 */
	private static int textWidth(Widget textWidget)
	{
		FontTypeFace font = textWidget.getFont();
		if (font == null)
		{
			return textWidget.getOriginalWidth();
		}
		return font.getTextWidth(Text.removeTags(textWidget.getText()));
	}

	/**
	 * The optional "[Team Name] " prefix (only the name within the brackets is
	 * team-colored; a trailing space follows) shown before a player's name when
	 * the config toggle is on, or "" when off.
	 */
	private String teamPrefix(TeamInfo team)
	{
		if (!config.showTeamNameInChat())
		{
			return "";
		}
		return "[" + ColorUtil.wrapWithColorTag(team.getName(), team.getColor()) + "] ";
	}

	/**
	 * Broadcasts look like "Player X received a drop: Twisted bow." — if the
	 * message starts with a roster player's name, color just that name in the
	 * team color and leave the rest of the line untouched, consistent with the
	 * public/clan chat coloring. Matching is done on the raw value (names never
	 * contain markup) with in-game non-breaking spaces treated as regular spaces.
	 */
	private void tagBroadcast(MessageNode messageNode)
	{
		String value = messageNode.getValue();
		if (value == null || value.isEmpty())
		{
			return;
		}

		String haystack = value.replace('\u00A0', ' ');
		for (TeamInfo team : registry.getTeams())
		{
			for (String player : team.getPlayerNames())
			{
				String candidate = player.replace('\u00A0', ' ').trim();
				if (candidate.isEmpty()
					|| !haystack.regionMatches(true, 0, candidate, 0, candidate.length()))
				{
					continue;
				}
				// Require a word boundary so "Bob" doesn't match "Bobby has..."
				if (haystack.length() > candidate.length()
					&& Character.isLetterOrDigit(haystack.charAt(candidate.length())))
				{
					continue;
				}

				String namePart = value.substring(0, candidate.length());
				String rest = value.substring(candidate.length());
				String colored = teamPrefix(team)
					+ ColorUtil.wrapWithColorTag(namePart, team.getColor()) + rest;

				clientThread.invokeLater(() -> {
					messageNode.setValue(colored);
					client.refreshChat();
				});
				return;
			}
		}
	}
}

package com.eventteams;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.awt.Color;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.util.Text;

/**
 * Holds the list of teams and a fast name -> team lookup. Player names are
 * normalized (case folded, whitespace collapsed) since RuneScape names are
 * case-insensitive and can come in with inconsistent spacing from pasted CSV.
 */
public class TeamRegistry
{
	private final Gson gson;
	private final Gson shareGson;

	private final List<TeamInfo> teams = new ArrayList<>();
	private final Map<String, TeamInfo> byNormalizedName = new LinkedHashMap<>();

	public TeamRegistry(Gson gson)
	{
		this.gson = gson;
		this.shareGson = gson.newBuilder().setPrettyPrinting().create();
	}

	public List<TeamInfo> getTeams()
	{
		return teams;
	}

	public void addTeam(TeamInfo team)
	{
		teams.add(team);
		reindex();
	}

	public void removeTeam(TeamInfo team)
	{
		teams.remove(team);
		reindex();
	}

	/** Replaces the whole roster, e.g. from a clipboard import. */
	public void setTeams(List<TeamInfo> newTeams)
	{
		teams.clear();
		teams.addAll(newTeams);
		reindex();
	}

	/** Call after mutating a team's name/color/roster in place. */
	public void reindex()
	{
		byNormalizedName.clear();
		for (TeamInfo team : teams)
		{
			for (String rawName : team.getPlayerNames())
			{
				String normalized = normalize(rawName);
				if (!normalized.isEmpty())
				{
					byNormalizedName.put(normalized, team);
				}
			}
		}
	}

	public TeamInfo getTeamForPlayer(String playerName)
	{
		if (playerName == null)
		{
			return null;
		}
		return byNormalizedName.get(normalize(playerName));
	}

	public Color getColorForPlayer(String playerName)
	{
		TeamInfo team = getTeamForPlayer(playerName);
		return team == null ? null : team.getColor();
	}

	public static String normalize(String name)
	{
		// Text.standardize/removeTags handles the <img=..> icon tags RuneScape
		// prefixes some names with (e.g. clan rank icons); collapse remaining
		// whitespace and lowercase so "Zezima", "zezima", "Zezima " all match.
		String cleaned = Text.removeTags(name).replace('\u00A0', ' ').trim();
		return cleaned.toLowerCase();
	}

	public static List<String> parseCsv(String csv)
	{
		List<String> names = new ArrayList<>();
		if (csv == null)
		{
			return names;
		}
		for (String part : csv.split("[,\\r\\n]+"))
		{
			String trimmed = part.trim();
			if (!trimmed.isEmpty())
			{
				names.add(trimmed);
			}
		}
		return names;
	}

	// --- persistence -------------------------------------------------------

	private static class StoredTeam
	{
		String name;
		int colorRgb;
		List<String> playerNames;
	}

	public String serialize()
	{
		List<StoredTeam> stored = new ArrayList<>();
		for (TeamInfo team : teams)
		{
			StoredTeam s = new StoredTeam();
			s.name = team.getName();
			s.colorRgb = team.getColor().getRGB();
			s.playerNames = team.getPlayerNames();
			stored.add(s);
		}
		return gson.toJson(stored);
	}

	/** Replaces this registry's teams with the contents of a stored config JSON blob. */
	public void loadFromJson(String json)
	{
		teams.clear();
		if (json == null || json.isEmpty())
		{
			reindex();
			return;
		}

		Type listType = new TypeToken<List<StoredTeam>>()
		{
		}.getType();

		List<StoredTeam> stored = gson.fromJson(json, listType);
		if (stored != null)
		{
			for (StoredTeam s : stored)
			{
				TeamInfo team = new TeamInfo(s.name, new Color(s.colorRgb, true));
				team.setPlayerNames(s.playerNames == null ? new ArrayList<>() : s.playerNames);
				teams.add(team);
			}
		}
		reindex();
	}

	// --- clipboard share format ---------------------------------------------
	// Human-editable, unlike the internal storage blob:
	// [{"name": "Team A", "color": "#E74C3C", "players": ["Zezima", "B0aty"]}]

	private static class ShareTeam
	{
		String name;
		String color;
		List<String> players;
	}

	public String toShareJson()
	{
		List<ShareTeam> out = new ArrayList<>();
		for (TeamInfo team : teams)
		{
			ShareTeam s = new ShareTeam();
			s.name = team.getName();
			s.color = String.format("#%06X", team.getColor().getRGB() & 0xFFFFFF);
			s.players = new ArrayList<>(team.getPlayerNames());
			out.add(s);
		}
		return shareGson.toJson(out);
	}

	/** Parses the share format leniently; returns null only if the JSON is unusable. */
	public List<TeamInfo> fromShareJson(String json)
	{
		List<ShareTeam> stored;
		try
		{
			Type listType = new TypeToken<List<ShareTeam>>()
			{
			}.getType();
			stored = shareGson.fromJson(json, listType);
		}
		catch (JsonSyntaxException ex)
		{
			return null;
		}

		if (stored == null)
		{
			return null;
		}

		List<TeamInfo> result = new ArrayList<>();
		int index = 1;
		for (ShareTeam s : stored)
		{
			if (s == null)
			{
				continue;
			}

			Color color = Color.WHITE;
			if (s.color != null)
			{
				try
				{
					color = Color.decode(s.color.trim());
				}
				catch (NumberFormatException ignored)
				{
				}
			}

			TeamInfo team = new TeamInfo(
				s.name == null || s.name.trim().isEmpty() ? "Team " + index : s.name.trim(), color);
			if (s.players != null)
			{
				for (String player : s.players)
				{
					if (player != null && !player.trim().isEmpty())
					{
						team.getPlayerNames().add(player.trim());
					}
				}
			}
			result.add(team);
			index++;
		}
		return result;
	}
}

package com.eventteams;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.FriendsChatMember;
import net.runelite.api.FriendsChatRank;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.Text;

/**
 * Draws team-colored names above players in the game world, mirroring the
 * technique the core PlayerIndicators plugin uses (draw text at the player's
 * canvas text location) — just keyed off our team registry instead of
 * friend/clan flags. Minimap dots live in {@link EventTeamsMinimapOverlay},
 * which needs a different overlay layer.
 *
 * The name rendering intentionally duplicates PlayerIndicatorsOverlay's exact
 * layout math (zOffset, rank-icon offsets, sanitized name) and draws at a
 * higher priority, so for players core Player Indicators already labels
 * (friends/clan), our team-colored name paints pixel-for-pixel over the top of
 * theirs — same rank icon, different color — instead of overlapping it.
 */
public class EventTeamsOverlay extends Overlay
{
	// Same value as PlayerIndicatorsOverlay.ACTOR_OVERHEAD_TEXT_MARGIN; keep in
	// sync or the two names drift apart vertically and both become visible.
	private static final int ACTOR_OVERHEAD_TEXT_MARGIN = 40;

	private final Client client;
	private final EventTeamsConfig config;
	private final TeamRegistry registry;
	private final ChatIconManager chatIconManager;

	@Inject
	EventTeamsOverlay(Client client, EventTeamsConfig config, TeamRegistry registry,
		ChatIconManager chatIconManager)
	{
		this.client = client;
		this.config = config;
		this.registry = registry;
		this.chatIconManager = chatIconManager;
		setPosition(OverlayPosition.DYNAMIC);
		// Stay on the default UNDER_WIDGETS layer: that's where core Player
		// Indicators draws (it never calls setLayer), and layer ordering trumps
		// priority — an ABOVE_SCENE overlay always paints before UNDER_WIDGETS.
		// Within the shared layer, our higher priority renders after (on top
		// of) Player Indicators' PRIORITY_MED.
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightInWorld() && !config.highlightOnMinimap())
		{
			return null;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}

		for (Player player : worldView.players())
		{
			if (player == null || player.getName() == null)
			{
				continue;
			}

			Color color = registry.getColorForPlayer(player.getName());
			if (color == null)
			{
				continue;
			}

			// Never label the local player; you know which team you're on.
			if (config.highlightInWorld() && player != client.getLocalPlayer())
			{
				renderPlayerName(graphics, player, color);
			}
		}

		return null;
	}

	private void renderPlayerName(Graphics2D graphics, Player player, Color color)
	{
		String name = Text.sanitize(player.getName());
		int zOffset = player.getLogicalHeight() + ACTOR_OVERHEAD_TEXT_MARGIN;
		Point textLocation = player.getCanvasTextLocation(graphics, name, zOffset);
		if (textLocation == null)
		{
			return;
		}

		BufferedImage rankImage = getRankImage(player);
		if (rankImage != null)
		{
			// We deliberately don't draw the rank icon ourselves, but core
			// Player Indicators shifts the name right by half the icon's width
			// when one applies — mirror that shift so our text still lands
			// exactly on top of theirs (their icon shows through unchanged).
			textLocation = new Point(textLocation.getX() + rankImage.getWidth() / 2, textLocation.getY());
		}

		OverlayUtil.renderTextLocation(graphics, textLocation, name, color);
	}

	/**
	 * Same icon and precedence core Player Indicators shows: friends chat rank
	 * first, otherwise clan rank title.
	 */
	private BufferedImage getRankImage(Player player)
	{
		if (player.isFriendsChatMember())
		{
			FriendsChatManager friendsChatManager = client.getFriendsChatManager();
			FriendsChatMember member = friendsChatManager == null
				? null : friendsChatManager.findByName(Text.removeTags(player.getName()));
			if (member != null && member.getRank() != FriendsChatRank.UNRANKED)
			{
				return chatIconManager.getRankImage(member.getRank());
			}
		}

		if (player.isClanMember())
		{
			ClanChannel clanChannel = client.getClanChannel();
			ClanSettings clanSettings = client.getClanSettings();
			if (clanChannel != null && clanSettings != null)
			{
				ClanChannelMember member = clanChannel.findMember(player.getName());
				if (member != null)
				{
					ClanTitle title = clanSettings.titleForRank(member.getRank());
					if (title != null)
					{
						return chatIconManager.getRankImage(title);
					}
				}
			}
		}

		return null;
	}
}

package com.eventteams;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

/**
 * One bingo team: a display name, a color, and the CSV roster of player names
 * as the user typed them (kept around so the panel can re-render the raw list
 * for editing without lossy round-tripping through the normalized lookup map).
 */
public class TeamInfo
{
	private String name;
	private Color color;
	private List<String> playerNames = new ArrayList<>();

	public TeamInfo(String name, Color color)
	{
		this.name = name;
		this.color = color;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public Color getColor()
	{
		return color;
	}

	public void setColor(Color color)
	{
		this.color = color;
	}

	public List<String> getPlayerNames()
	{
		return playerNames;
	}

	public void setPlayerNames(List<String> playerNames)
	{
		this.playerNames = playerNames;
	}
}

package com.eventteams;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.Insets;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JColorChooser;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar UI. One card per team: editable name, color, the team's players each
 * with a live online dot (from the clan channel), a one-at-a-time add field,
 * and a clipboard paste for a JSON array of names. Top-level buttons copy or
 * replace the entire team setup as shareable JSON.
 *
 * Uses PluginPanel's default wrapping (single fixed-width column, vertical
 * scrollbar only) so nothing can overflow horizontally.
 */
public class EventTeamsPanel extends PluginPanel
{
	private static final Color ONLINE_COLOR = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color OFFLINE_COLOR = ColorScheme.MEDIUM_GRAY_COLOR;

	private final EventTeamsPlugin plugin;
	private final TeamRegistry registry;

	private final JPanel teamsContainer = new JPanel(new DynamicGridLayout(0, 1, 0, 8));

	// Re-run on every status update so player rows recolor in place without a
	// full rebuild (a rebuild would steal focus from the add-player fields).
	private final List<Runnable> statusUpdaters = new ArrayList<>();
	private Map<String, Integer> onlineWorlds = Collections.emptyMap();

	// Offline sections are collapsed unless toggled open; keyed by team so the
	// choice survives the rebuilds that status changes trigger.
	private final Map<TeamInfo, Boolean> offlineExpanded = new HashMap<>();

	public EventTeamsPanel(EventTeamsPlugin plugin, TeamRegistry registry)
	{
		this.plugin = plugin;
		this.registry = registry;

		JPanel actions = new JPanel(new DynamicGridLayout(0, 1, 0, 4));

		JButton addTeamButton = new JButton("+ Add Team");
		addTeamButton.addActionListener(e -> {
			registry.addTeam(new TeamInfo("Team " + (registry.getTeams().size() + 1), randomColor()));
			plugin.saveTeams();
			rebuildTeamsUi();
		});

		JButton exportButton = new JButton("Export teams JSON");
		exportButton.setToolTipText("Copy all teams (names, colors, players) to the clipboard as JSON");
		exportButton.addActionListener(e ->
			Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new StringSelection(registry.toShareJson()), null));

		JButton importButton = new JButton("Import teams JSON");
		importButton.setToolTipText("Replace all teams with JSON from the clipboard (the format Export produces)");
		importButton.addActionListener(e -> importTeamsFromClipboard());

		actions.add(addTeamButton);
		actions.add(exportButton);
		actions.add(importButton);

		add(actions);
		add(teamsContainer);

		rebuildTeamsUi();
	}

	private void rebuildTeamsUi()
	{
		statusUpdaters.clear();
		teamsContainer.removeAll();
		for (TeamInfo team : registry.getTeams())
		{
			teamsContainer.add(buildTeamCard(team));
		}
		teamsContainer.revalidate();
		teamsContainer.repaint();
	}

	private JPanel buildTeamCard(TeamInfo team)
	{
		JPanel card = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 6, 6, 6)));

		JTextField nameField = new JTextField(team.getName());
		nameField.addActionListener(e -> saveTeamName(team, nameField));
		nameField.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				saveTeamName(team, nameField);
			}
		});

		JButton colorButton = new JButton("Color");
		colorButton.setBackground(team.getColor());
		colorButton.addActionListener(e -> {
			Color chosen = JColorChooser.showDialog(card, "Team color", team.getColor());
			if (chosen != null)
			{
				team.setColor(chosen);
				colorButton.setBackground(chosen);
				plugin.saveTeams();
			}
		});

		JButton removeButton = new JButton("✕");
		removeButton.setMargin(new Insets(0, 6, 0, 6));
		removeButton.setToolTipText("Remove team");
		removeButton.addActionListener(e -> {
			registry.removeTeam(team);
			plugin.saveTeams();
			rebuildTeamsUi();
		});

		JPanel nameRow = new JPanel(new BorderLayout(4, 0));
		nameRow.add(nameField, BorderLayout.CENTER);
		nameRow.add(removeButton, BorderLayout.EAST);

		card.add(nameRow);
		card.add(colorButton);

		// Online players first, offline below, each alphabetical.
		List<String> online = new ArrayList<>();
		List<String> offline = new ArrayList<>();
		for (String playerName : team.getPlayerNames())
		{
			(isOnline(playerName) ? online : offline).add(playerName);
		}
		online.sort(String.CASE_INSENSITIVE_ORDER);
		offline.sort(String.CASE_INSENSITIVE_ORDER);

		if (!online.isEmpty())
		{
			card.add(sectionHeader("Online"));
			for (String playerName : online)
			{
				card.add(buildPlayerRow(team, playerName));
			}
		}
		if (!offline.isEmpty())
		{
			boolean expanded = offlineExpanded.getOrDefault(team, false);
			card.add(offlineToggle(team, offline.size(), expanded));
			if (expanded)
			{
				for (String playerName : offline)
				{
					card.add(buildPlayerRow(team, playerName));
				}
			}
		}

		JTextField addField = new JTextField();
		JButton addButton = new JButton("+");
		addButton.setMargin(new Insets(0, 6, 0, 6));
		Runnable submitPlayer = () -> {
			String name = addField.getText().trim();
			if (name.isEmpty())
			{
				return;
			}
			if (!containsName(team, name))
			{
				team.getPlayerNames().add(name);
				registry.reindex();
				plugin.saveTeams();
			}
			rebuildTeamsUi();
		};
		addField.addActionListener(e -> submitPlayer.run());
		addButton.addActionListener(e -> submitPlayer.run());

		JPanel addRow = new JPanel(new BorderLayout(4, 0));
		addRow.add(addField, BorderLayout.CENTER);
		addRow.add(addButton, BorderLayout.EAST);
		card.add(addRow);

		return card;
	}

	private static JLabel sectionHeader(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(Font.PLAIN, 11f));
		return label;
	}

	/** Muted, clickable "Offline (n)" header that expands/collapses the section. */
	private JLabel offlineToggle(TeamInfo team, int count, boolean expanded)
	{
		JLabel label = sectionHeader((expanded ? "▾ " : "▸ ") + "Offline (" + count + ")");
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.setToolTipText(expanded ? "Hide offline players" : "Show offline players");
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				offlineExpanded.put(team, !expanded);
				rebuildTeamsUi();
			}
		});
		return label;
	}

	private JPanel buildPlayerRow(TeamInfo team, String playerName)
	{
		JLabel dot = new JLabel("●");
		JLabel nameLabel = new JLabel(playerName);
		JLabel worldLabel = new JLabel();
		worldLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JButton removeButton = new JButton("✕");
		removeButton.setMargin(new Insets(0, 4, 0, 4));
		removeButton.setToolTipText("Remove " + playerName);
		removeButton.addActionListener(e -> {
			team.getPlayerNames().remove(playerName);
			registry.reindex();
			plugin.saveTeams();
			rebuildTeamsUi();
		});

		JPanel east = new JPanel(new BorderLayout(4, 0));
		east.add(worldLabel, BorderLayout.CENTER);
		east.add(removeButton, BorderLayout.EAST);

		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.add(dot, BorderLayout.WEST);
		row.add(nameLabel, BorderLayout.CENTER);
		row.add(east, BorderLayout.EAST);

		Runnable updater = () -> {
			Integer world = onlineWorlds.get(TeamRegistry.normalize(playerName));
			boolean online = world != null;
			dot.setForeground(online ? ONLINE_COLOR : OFFLINE_COLOR);
			worldLabel.setText(online ? "W" + world : "");
			nameLabel.setToolTipText(online
				? playerName + " is online (world " + world + ")"
				: playerName + " is offline (or not in the clan channel)");
		};
		updater.run();
		statusUpdaters.add(updater);

		return row;
	}

	private void importTeamsFromClipboard()
	{
		String clip = readClipboard();
		List<TeamInfo> imported = clip == null ? null : registry.fromShareJson(clip);
		if (imported == null)
		{
			JOptionPane.showMessageDialog(this,
				"Clipboard doesn't contain valid teams JSON.\n"
					+ "Expected: [{\"name\": ..., \"color\": \"#RRGGBB\", \"players\": [...]}]",
				"Paste teams", JOptionPane.WARNING_MESSAGE);
			return;
		}

		if (!registry.getTeams().isEmpty()
			&& JOptionPane.showConfirmDialog(this,
				"Replace all " + registry.getTeams().size() + " existing team(s)?",
				"Paste teams", JOptionPane.OK_CANCEL_OPTION) != JOptionPane.OK_OPTION)
		{
			return;
		}

		registry.setTeams(imported);
		plugin.saveTeams();
		rebuildTeamsUi();
	}

	private static boolean containsName(TeamInfo team, String name)
	{
		String normalized = TeamRegistry.normalize(name);
		for (String existing : team.getPlayerNames())
		{
			if (TeamRegistry.normalize(existing).equals(normalized))
			{
				return true;
			}
		}
		return false;
	}

	private void saveTeamName(TeamInfo team, JTextField field)
	{
		String name = field.getText().trim();
		if (!name.isEmpty() && !name.equals(team.getName()))
		{
			team.setName(name);
			plugin.saveTeams();
		}
	}

	private static String readClipboard()
	{
		try
		{
			return (String) Toolkit.getDefaultToolkit().getSystemClipboard()
				.getData(DataFlavor.stringFlavor);
		}
		catch (Exception ex)
		{
			return null;
		}
	}

	/** Called by the plugin whenever the clan channel updates; safe off the EDT. */
	public void updateOnlineStatus(Map<String, Integer> onlineWorlds)
	{
		SwingUtilities.invokeLater(() -> {
			// Row order depends on who's online, so a membership change needs a
			// rebuild; a mere world hop only needs the in-place label updates
			// (which don't steal focus from the add-player fields).
			boolean orderChanged = !onlineRosterNames(onlineWorlds).equals(onlineRosterNames(this.onlineWorlds));
			this.onlineWorlds = onlineWorlds;
			if (orderChanged)
			{
				rebuildTeamsUi();
			}
			else
			{
				for (Runnable updater : statusUpdaters)
				{
					updater.run();
				}
			}
		});
	}

	private boolean isOnline(String playerName)
	{
		return onlineWorlds.containsKey(TeamRegistry.normalize(playerName));
	}

	/** Normalized roster names currently online per the given channel snapshot. */
	private Set<String> onlineRosterNames(Map<String, Integer> worlds)
	{
		Set<String> out = new HashSet<>();
		for (TeamInfo team : registry.getTeams())
		{
			for (String playerName : team.getPlayerNames())
			{
				String normalized = TeamRegistry.normalize(playerName);
				if (worlds.containsKey(normalized))
				{
					out.add(normalized);
				}
			}
		}
		return out;
	}

	private static Color randomColor()
	{
		java.util.Random r = new java.util.Random();
		return Color.getHSBColor(r.nextFloat(), 0.65f, 0.95f);
	}
}
